import re
from datetime import datetime

_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_OPTED_OUT_VALUES = {"y", "yes", "true", "1"}


def _normalize_email(raw):
    s = raw
    m = re.search(r"<([^<>]*)>", s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            s = local + "@gmail.com"
    return s


def _is_valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    s = raw.lower()
    cuts = [i for i in (s.find("ext"), s.find("x"), s.find("#")) if i != -1]
    if cuts:
        s = s[:min(cuts)]
    digits = "".join(c for c in s if "0" <= c <= "9")
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _normalize_zip(raw):
    s = raw.strip()
    m = re.fullmatch(r"([0-9]{4,5})-[0-9]{4}", s)  # ZIP+4, allowing Excel-trimmed prefix
    if m:
        s = m.group(1)
    if re.fullmatch(r"[0-9]{4}", s):
        s = "0" + s
    return s if re.fullmatch(r"[0-9]{5}", s) else ""


def _normalize_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def dedupe_contacts(rows):
    # Normalize every row and drop rows with no valid email or phone (rule 9).
    recs = []
    for idx, row in enumerate(rows):
        email = _normalize_email(row.get("email", ""))
        phone = _normalize_phone(row.get("phone", ""))
        email_ok = _is_valid_email(email)
        phone_ok = _is_valid_phone(phone)
        if not (email_ok or phone_ok):
            continue
        source = row.get("source", "").strip().lower()
        recs.append({
            "idx": idx,
            "first": _normalize_name(row.get("first_name", "")),
            "last": _normalize_name(row.get("last_name", "")),
            "zip": _normalize_zip(row.get("zip", "")),
            "email": email,
            "email_ok": email_ok,
            "phone": phone,
            "phone_ok": phone_ok,
            "source": source,
            "manual": source == "manual",
            "tags": {t.strip().lower()
                     for t in re.split(r"[;,]", row.get("tags", ""))
                     if t.strip()},
            "opted_out": row.get("opted_out", "").strip().lower() in _OPTED_OUT_VALUES,
            "updated": _parse_updated(row["updated"]),
        })

    # Union-find: rows sharing a match key belong to the same person (rule 10).
    parent = list(range(len(recs)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    first_seen = {}
    for i, r in enumerate(recs):
        keys = []
        if r["email_ok"]:
            keys.append(("email", r["email"]))
        if r["phone_ok"] and r["last"]:
            keys.append(("phone", r["phone"], r["last"].casefold()))
        for key in keys:
            if key in first_seen:
                union(first_seen[key], i)
            else:
                first_seen[key] = i

    # Groups in order of earliest row: indexes are visited ascending,
    # so dict insertion order matches first appearance.
    groups = {}
    for i in range(len(recs)):
        groups.setdefault(find(i), []).append(i)

    def pick(members, value, ok):
        cands = [recs[i] for i in members if ok(recs[i])]
        if not cands:
            return ""
        cands.sort(key=lambda r: r["idx"])                        # earliest input row
        cands.sort(key=lambda r: r["updated"], reverse=True)      # most recent update
        cands.sort(key=lambda r: not r["manual"])                 # manual rows first
        return value(cands[0])

    output = []
    for members in groups.values():
        grp = [recs[i] for i in members]
        output.append({
            "first_name": pick(members, lambda r: r["first"], lambda r: r["first"] != ""),
            "last_name": pick(members, lambda r: r["last"], lambda r: r["last"] != ""),
            "zip": pick(members, lambda r: r["zip"], lambda r: r["zip"] != ""),
            "email": pick(members, lambda r: r["email"], lambda r: r["email_ok"]),
            "phone": pick(members, lambda r: r["phone"], lambda r: r["phone_ok"]),
            "source": pick(members, lambda r: r["source"], lambda r: r["source"] != ""),
            "tags": ";".join(sorted(set().union(*(r["tags"] for r in grp)))),
            "opted_out": "Y" if any(r["opted_out"] for r in grp) else "N",
            "updated": max(r["updated"] for r in grp).strftime("%Y-%m-%d"),
        })
    return output
